INSERT INTO `categories` VALUES (7,'Builder Gel','builder-gel','✨','High-viscosity sculpting gels for durable extensions, apex building, and structural reinforcement.',1,4,'2026-09-19 07:10:55','2026-10-21 14:55:56'),(3,'Gel Polishes','gel-polishes','🎨','Master salon gel polish collections with single-stroke opacity, self-leveling viscosity, and 4+ weeks wear.',1,7,'2026-09-07 10:21:02','2026-10-21 14:55:56'),(8,'Base Coat','base-coat','🛡️','Superior adhesion base coats designed to protect natural nails and prevent lifting for 4+ weeks.',0,2,'2026-09-26 13:16:40','2026-10-22 00:26:17'),(9,'BIAB','biab','💧','Builder In A Bottle liquid gels for natural nail overlays, apex building, and extreme strength.',1,2,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(10,'Blooming Gel','blooming-gel','🌸','Fast-spreading bloom gels creating effortless marble, watercolor, and botanical floral nail art.',1,3,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(11,'Carving Gel','carving-gel','🏺','3D moldable non-sticky carving gels for sculpted relief nail art, figurines, and emboss florals.',1,5,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(12,'Cat Eye Gels','cat-eye-gels','👁️','Magnetic chameleon and velvet cat eye gels with celestial refractive shimmer and deep galactic luster.',1,6,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(27,'Air Brush','air-brush','💨','Professional salon airbrush nail systems delivering flawless gradient ombré, micro-mist spray, and couture nail art.',1,22,'2026-10-22 03:41:37','2026-10-22 03:41:37'),(13,'Matte Top Coat','matte-top-coat','🌫️','Cashmere-smooth velvety matte top coats with non-wipe formula and anti-scratch finish.',1,8,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(14,'Metallic Gel','metallic-gel','🪞','Liquid mirror chrome and molten metallic gels for high-definition line art and chrome accents.',1,9,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(15,'Mixing Gel','mixing-gel','🧪','Crystal-clear dilution and blending gels for custom gradients, glitters, and ombré shading.',0,10,'2026-09-26 13:16:40','2026-10-22 00:26:14'),(16,'Painting Gel','painting-gel','🖌️','Ultra-pigmented fine art painting gels designed for precision linework and detailing.',1,11,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(17,'Platinum Gel','platinum-gel','⭐','High-density micro-foil and platinum glitter gels delivering maximum diamond sparkle.',1,12,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(18,'Polygel','polygel','💎','Hybrid acrylic-gel formula offering featherweight feel with unbreakable strength.',1,13,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(19,'Primer','primer','🧴','Acid-free dehydrating bonding primers maximizing gel longevity without natural nail damage.',1,14,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(20,'Reflective Polish','reflective-polish','✨','Disco flash reflective glitter gels illuminating with blinding brilliance under direct flash.',1,15,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(21,'Rhinestone Gel','rhinestone-gel','💍','Extra-strong no-wipe crystal adhesive gel securing gems, pearls, and charms firmly.',1,16,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(22,'Rubber Base','rubber-base','🌿','Flexible 5-in-1 rubber bases providing shock absorption and leveling for brittle nails.',1,17,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(23,'Solid Glue Gel','solid-glue-gel','🏷️','Solid adhesive gels for press-on tips and soft gel extensions with zero air bubbles.',1,18,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(24,'Spider Gel','spider-gel','🕸️','Elastic matrix spider gels pulling crisp geometric lines and spiderweb nail art in seconds.',1,19,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(25,'Top Coats','top-coats','💎','Glass-like high shine tempered top coats providing scratch-resistant long-lasting protection.',1,20,'2026-09-26 13:16:40','2026-10-21 14:55:56'),(26,'6-in-1 Top Coat','6-in-1-top-coat','👑','Diamond-hard multifunctional top coat engineered for sealing, leveling, and extreme durability.',1,21,'2026-09-26 13:16:40','2026-10-21 14:55:56');
