INSERT INTO `page_contents` VALUES (1,'home','hero','{\"slides\": [{\"cta_url\": \"/products\", \"bg_image\": \"/images/banners/hero-slide-main-recolte.png\", \"cta_text\": \"SHOP NOW\", \"subtitle\": \"Premium Nail Products for Professionals & Enthusiasts\", \"script_line\": \"Create • Express • Shine\", \"sub_descriptor\": \"NAILS • BEAUTY • YOU\"}, {\"cta_url\": \"/products?category=Gel+Polishes\", \"bg_image\": \"http://localhost:8000/images/banners/hero-slide-spotlight-96.png\", \"cta_text\": \"EXPLORE 96 PALETTES\", \"subtitle\": \"96 Master Palette Gel Polish Shades Engineered for Runway Manicures & Salon Artists\", \"script_line\": \"Curated Color Harmony\", \"sub_descriptor\": \"SPOTLIGHT ATELIER • 96 SALON SHADES\"}, {\"cta_url\": \"/products?category=Nail+Tools+%26+Kits\", \"bg_image\": \"http://localhost:8000/images/banners/hero-slide-dust-collector.png\", \"cta_text\": \"DISCOVER EQUIPMENT\", \"subtitle\": \"High-Powered Turbo Ventilation & Micro-Filtration for a Clean, Dust-Free Atelier Environment\", \"script_line\": \"Pure Salon Comfort\", \"sub_descriptor\": \"PROFESSIONAL SALON TECH • AIR PURITY\"}, {\"cta_url\": \"/products?category=Nail+Tools+%26+Kits\", \"bg_image\": \"http://localhost:8000/images/banners/hero-slide-uv-led-lamp.png\", \"cta_text\": \"SHOP UV/LED LAMPS\", \"subtitle\": \"Salon-Grade Smart Timing & 120s Sensor Curing for Mirror-Shine Durability and Zero Heat Spikes\", \"script_line\": \"Fast & Flawless Curing\", \"sub_descriptor\": \"ADVANCED UV/LED TECH • DUAL OPTICS\"}, {\"cta_url\": \"/products?category=Nail+Art+%26+Accents\", \"bg_image\": \"http://localhost:8000/images/banners/hero-slide-cat-eye-60.png\", \"cta_text\": \"SHOP CAT EYE GELS\", \"subtitle\": \"60 Dimensional Cat-Eye Magnetic Gels with Pearlescent Beams & Multi-Angle Velvet Reflections\", \"script_line\": \"Chameleon Magnetic Depth\", \"sub_descriptor\": \"VELVET MAGNETIC COUTURE • 60 SHADES\"}], \"cta_url\": \"/products\", \"bg_image\": \"/images/banners/hero-slide-main-recolte.png\", \"cta_text\": \"SHOP NOW\", \"subtitle\": \"Premium Nail Products for Professionals & Enthusiasts\", \"brand_title\": \"Recolte\", \"script_line\": \"Create • Express • Shine\", \"sub_descriptor\": \"NAILS • BEAUTY • YOU\", \"brand_trademark\": \"®\"}','2026-09-07 10:21:02','2026-10-21 23:34:30'),(9,'home','trust_strip','{\"items\": [{\"sub\": \"Products\", \"icon\": \"diamond\", \"title\": \"Premium Quality\"}, {\"sub\": \"Formulas\", \"icon\": \"shield\", \"title\": \"Safe & Skin Friendly\"}, {\"sub\": \"Shipping\", \"icon\": \"truck\", \"title\": \"Fast & Reliable\"}, {\"sub\": \"Always\", \"icon\": \"support\", \"title\": \"Expert Support\"}, {\"sub\": \"Professionals\", \"icon\": \"star\", \"title\": \"Trusted by\"}]}','2026-09-08 22:31:38','2026-10-21 23:34:30'),(10,'home','categories_section','{\"title\": \"Shop by Category\", \"subtitle\": \"Everything you need for perfect nails\", \"categories\": [{\"link\": \"/products?category=Gel+Polishes\", \"image\": \"http://localhost:8000/images/products/recolte-cat-nail-kits.jpg\", \"title\": \"Shades\", \"btn_text\": \"Shop Now\"}, {\"link\": \"/products\", \"image\": \"http://localhost:8000/images/products/recolte-cat-uv-lamps.jpg\", \"title\": \"UV Lamps\", \"btn_text\": \"Shop Now\"}, {\"link\": \"/products?category=Builder+Gel\", \"image\": \"http://localhost:8000/images/products/recolte-cat-builder-gel.jpg\", \"title\": \"Builder Gel\", \"btn_text\": \"Shop Now\"}, {\"link\": \"/products?category=Cat+Eye+Gels\", \"image\": \"http://localhost:8000/images/products/recolte-cat-tips.jpg\", \"title\": \"CATE EYES\", \"btn_text\": \"Shop Now\"}]}','2026-09-08 22:31:38','2026-10-21 23:34:30'),(2,'home','pillars','{\"badge\": \"Nails by Recolte • Paris\", \"title\": \"Unlock Your Best Nails: Trusted by Nail Enthusiasts\", \"card1_num\": \"01 / ATELIER FORMULATION\", \"card2_num\": \"02 / GENTLE HEALTH\", \"card1_desc\": \"Every formulation is hand-layered with salon-grade Japanese gel resins, guaranteeing true-to-life luster, optical chrome effects, and chip-free durability that withstands daily life.\", \"card2_desc\": \"Engineered for effortless removal without harsh drills or acetone damage, preserving your natural nail keratin bed intact.\", \"card1_image\": \"https://images.unsplash.com/photo-1519014816548-bf5fe059798b?auto=format&fit=crop&w=600&q=80\", \"card1_title\": \"Japanese Gel Craftsmanship\", \"card2_image\": \"https://images.unsplash.com/photo-1599458356314-91ca8ca575c5?auto=format&fit=crop&w=600&q=80\", \"card2_title\": \"Zero Natural Nail Damage\"}','2026-09-07 10:21:02','2026-09-29 13:55:29'),(3,'home','rituals','{\"badge\": \"RADIANT NAIL RITUALS\", \"title\": \"The Art of Parisian Nail Care\", \"subtitle\": \"Explore our complete suite of handcrafted luxury manicures, salon gel polishes, and organic botanical care.\", \"card1_img\": \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors.jpg\", \"card1_sub\": \"Master 208 shades suite\", \"card2_img\": \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_4_.jpg\", \"card2_sub\": \"Velvet magnetic depth\", \"card3_img\": \"/uploads/products/catalog/BUILDER_GEL_builder_gel_1_.jpg\", \"card3_sub\": \"Sculpting & apex overlays\", \"card4_img\": \"/uploads/products/catalog/TOP_COATS_top_coat_1_.png\", \"card4_sub\": \"Tempered mirror shield\", \"card1_title\": \"Gel Polishes\", \"card2_title\": \"Cat Eye Gels\", \"card3_title\": \"Builder Gels\", \"card4_title\": \"Top & Base Coats\", \"editorial_desc\": \"True beauty begins with nail health. Our dual-phase approach combines pure Japanese resins with fortifying care to deliver salon-perfect results without compromise.\", \"editorial_quote\": \"Nails are the period at the end of the sentence. They complete the look.\"}','2026-09-07 10:21:02','2026-09-26 13:36:03'),(4,'home','philosophy','{\"badge\": \"HAUTE ATELIER PHILOSOPHY\", \"title\": \"Timeless Nail Care. Ageless Beauty Starts Here.\", \"p1_desc\": \"Pure formulas free from harsh allergens, formaldehyde, and toluene to preserve natural nail bed vitality.\", \"p2_desc\": \"Crafted with premium salon resins and Japanese gels for 4+ weeks of chip-free wear.\", \"p3_desc\": \"Ergonomic custom brushes and self-leveling viscosity ensuring flawless single-stroke coverage.\", \"p1_title\": \"100% Non-Toxic & HEMA-Free\", \"p2_title\": \"High-Yield Salon Formulation\", \"p3_title\": \"Precision Application\"}','2026-09-07 10:21:02','2026-09-26 13:36:03'),(5,'home','instagram','{\"badge\": \"Atelier Community\", \"posts\": [{\"alt\": \"Recolte Salon Gel Application\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_0_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_0_1789736475.mp4\", \"poster\": \"\"}, {\"alt\": \"Crimson & Gold Atelier Waves\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_1_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_1_1789736475.mp4\", \"poster\": \"\"}, {\"alt\": \"Rose Gold Leopard Couture Art\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_2_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_2_1789736475.mp4\", \"poster\": \"\"}], \"title\": \"Join Our Nail Community\", \"handle\": \"@recolte_gelpolish\", \"btn_text\": \"Follow @recolte_gelpolish\", \"subtitle\": \"Follow @recolte_gelpolish for seasonal nail art tutorials, custom press-on launches, and salon-grade transformations.\", \"profile_url\": \"https://www.instagram.com/recolte_gelpolish/\"}','2026-09-07 10:21:02','2026-10-21 23:34:30'),(6,'about','story','{\"badge\": \"OUR ATELIER HERITAGE & VISION\", \"title\": \"Where Parisian Haute Couture Meets Organic Nail Science\", \"stat1_num\": \"4+ Weeks\", \"stat2_num\": \"100%\", \"stat3_num\": \"120K+\", \"stat4_num\": \"0%\", \"paragraphs\": [\"Founded in Paris, Recolte Nails was born from a singular atelier obsession: creating salon-grade gel systems and organic nail formulations that enhance your elegance without ever compromising the health of your natural nail bed.\", \"Every product in our archives is meticulously engineered using Japanese salon gels, optical chrome pigments, and self-leveling polymers to guarantee 4+ weeks of chip-free, luminous wear.\", \"Our philosophy bridges the world of runway aesthetics with pure botanical care. From our revolutionary HEMA-free Japanese salon gels to tempered top coats, we ensure that salon glamour and natural nail wellness coexist seamlessly.\"], \"stat1_label\": \"Chip-Free Salon Wear\", \"stat2_label\": \"Organic & Non-Toxic Formulas\", \"stat3_label\": \"Salon Products Delivered Worldwide\", \"stat4_label\": \"Natural Nail Damage Guarantee\"}','2026-09-07 10:21:02','2026-09-29 13:55:29'),(7,'about','pillars','{\"p1_desc\": \"Formulated with authentic Japanese salon gels, optical chrome, and high-refraction top coats for unmatched depth and strength.\", \"p1_icon\": \"🎨\", \"p2_desc\": \"We reject harmful chemicals. Our formulations prioritize skin-friendly, hypoallergenic ingredients that protect your natural nail bed.\", \"p2_icon\": \"🌿\", \"p3_desc\": \"Gentle soak-off formulations that release cleanly without harsh drills or excessive filing.\", \"p3_icon\": \"✨\", \"p4_desc\": \"Tested and approved by master nail artists across Paris, Milan, and Tokyo for flawless daily performance.\", \"p4_icon\": \"📐\", \"p1_title\": \"Japanese Gel Craftsmanship\", \"p2_title\": \"100% Non-Toxic & HEMA-Free\", \"p3_title\": \"Zero Damage Soak-Off\", \"p4_title\": \"Professional Salon Grade\"}','2026-09-07 10:21:02','2026-09-26 13:36:03'),(8,'about','steps','{\"step1_num\": \"01\", \"step1_tag\": \"STEP 1\", \"step2_num\": \"02\", \"step2_tag\": \"STEP 2\", \"step3_num\": \"03\", \"step3_tag\": \"STEP 3\", \"step4_num\": \"04\", \"step4_tag\": \"STEP 4\", \"header_tag\": \"FROM PARISIAN SKETCH TO YOUR DOORSTEP\", \"step1_desc\": \"Cleanse and dehydrate with Recolte Acid-Free Primer to create an optimal bonding anchor.\", \"step2_desc\": \"Apply Recolte Professional Base Coat or BIAB Liquid Builder to reinforce structure and curvature.\", \"step3_desc\": \"Apply high-density Japanese gel polishes, magnetic cat-eye glazes, or fine art painting gels.\", \"step4_desc\": \"Seal under Recolte High Gloss Tempered Top Coat or Velvet Matte for 35+ days of mirror protection.\", \"header_desc\": null, \"step1_title\": \"Precision Nail Preparation\", \"step2_title\": \"Base & Apex Architecture\", \"step3_title\": \"Pure Pigment Infusion\", \"step4_title\": \"Tempered Diamond Armor\", \"header_title\": \"The 4-Step Atelier Creation Journey\"}','2026-09-07 10:21:02','2026-10-21 12:46:14'),(12,'about','hero','{\"stories\": [{\"p1\": \"Born from a passion for runway aesthetics and damage-free natural nail care, <strong>Recolte Nails</strong> redefines modern manicures. We bridge the gap between instant, reusable luxury press-on art and professional-grade salon gel nail care.\", \"p2\": \"Every press-on set in our atelier is meticulously built with 7 layers of premium Japanese salon gel, hand-buffed with genuine pearl chrome, and shaped to your exact millimeter nail curve for a seamless 4-week wear that looks 100% salon-sculpted.\", \"img\": \"http://localhost:8000/images/banners/recolte-colors-showcase.jpg\", \"badge\": \"✦ HAUTE NAIL ATELIER & CRAFTSMANSHIP\", \"title\": \"Crafted for Beauty.\", \"title_highlight\": \"Engineered for Nail Health.\"}, {\"p1\": \"Unlike cheap factory plastics that snap and pop off, Recolte nail suites are built with the same multi-stage UV gel curing process used in Tokyo and Parisian high-end nail salons.\", \"p2\": \"The result is a glass-smooth apex with ultra-thin, flexible cuticle borders that mold invisibly against your nail bed with zero pinching or lifting.\", \"img\": \"http://localhost:8000/uploads/pages/about_hero_1_1789296055.jpg\", \"badge\": \"✦ 7-LAYER GEL ARCHITECTURE\", \"title\": \"Seven Optical Layers.\", \"title_highlight\": \"Zero salon waiting time.\"}, {\"p1\": \"We believe cuticle care is skincare. Our signature elixirs are cold-pressed in small batches, infusing pure Moroccan Argan and Damask Rose essential oils with suspended 24K cosmetic gold flakes.\", \"p2\": \"Deeply hydrates nail matrices, heals cracked skin, and stimulates rapid natural nail growth without greasy residue.\", \"img\": \"http://localhost:8000/uploads/pages/about_hero_2_1789296245.jpg\", \"badge\": \"✦ 24K BOTANICAL NOURISHMENT\", \"title\": \"Pure Damask Rose.\", \"title_highlight\": \"Infused with 24K Gold.\"}, {\"p1\": \"Finding your size should never be stressful. Send a quick photo of your hand next to a coin over WhatsApp, and our studio artists map your exact millimeter measurements in 2 minutes.\", \"p2\": \"Every order includes our salon prep suite: dual-grit etched buffer, medical adhesive tabs, liquid salon resin, and prep wipes in a keepsake velvet presentation box.\", \"img\": \"http://localhost:8000/uploads/pages/about_hero_3_1789296245.jpg\", \"badge\": \"✦ BESPOKE SIZING CONCIERGE\", \"title\": \"100% Guaranteed Fit.\", \"title_highlight\": \"Or we remake it free.\"}], \"btn1_url\": \"/products\", \"btn2_url\": \"https://wa.me/917016266727\", \"btn1_text\": \"Explore Nail Catalog\", \"btn2_text\": \"WhatsApp Sizing Help\", \"card_badge\": \"100% Damage-Free\", \"card_stat_num\": \"+120,000\", \"card_stat_label\": \"CUSTOM SETS DELIVERED\"}','2026-09-09 10:43:07','2026-10-21 23:55:14'),(11,'home','showcase','{\"image\": \"http://localhost:8000/images/banners/recolte-colors-showcase.jpg?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139?v=1789330139\", \"btn_url\": \"/products\", \"btn_text\": \"Find more\", \"description\": \"Dedicated to salon-grade perfection, Japanese gel formulas, and effortless everyday elegance.\", \"title_line1\": \"Colors that\", \"title_line2\": \"cultivate confidence\"}','2026-09-08 22:31:38','2026-10-21 23:34:30'),(13,'about','instagram','{\"tag\": \"Atelier Community\", \"badge\": \"Atelier Community\", \"posts\": [{\"alt\": \"Recolte Salon Gel Application\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_0_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_0_1789736475.mp4\", \"poster\": \"\"}, {\"alt\": \"Crimson & Gold Atelier Waves\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_1_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_1_1789736475.mp4\", \"poster\": \"\"}, {\"alt\": \"Rose Gold Leopard Couture Art\", \"link\": \"https://www.instagram.com/recolte_gelpolish/\", \"image\": \"http://localhost:8000/uploads/pages/about_insta_video_2_1789736475.mp4\", \"video\": \"http://localhost:8000/uploads/pages/about_insta_video_2_1789736475.mp4\", \"poster\": \"\"}], \"title\": \"Join Our Nail Community\", \"handle\": \"@recolte_gelpolish\", \"btn_text\": \"Follow @recolte_gelpolish\", \"subtitle\": \"Follow @recolte_gelpolish for seasonal nail art tutorials, custom press-on launches, and salon-grade transformations.\", \"profile_url\": \"https://www.instagram.com/recolte_gelpolish/\"}','2026-09-09 10:43:07','2026-10-21 12:46:14'),(14,'about','concierge','{\"desc\": \"Have custom design inspiration or unique nail dimensions? Connect directly with our Parisian studio specialists on WhatsApp for 1-on-1 sizing guidance, shape matching, and express atelier crafting.\", \"img1\": \"http://localhost:8000/images/products/recolte-cat-gel-polish.jpg\", \"img2\": \"http://localhost:8000/images/products/recolte-cat-top-coat.jpg\", \"img3\": \"http://localhost:8000/images/products/recolte-cat-painting-gel.jpg\", \"badge\": \"Private Atelier Service\", \"title\": \"Your Dream Manicure, Curated in Real-Time.\", \"f1_desc\": \"Millimeter curve fit\", \"f2_desc\": \"Send Pinterest & photos\", \"f3_desc\": \"Full prep & glue kit\", \"btn1_url\": \"https://wa.me/917016266727?text=Hello+Recolte+Nails%2C+I+would+like+to+inquire+about+a+custom+order.\", \"btn2_url\": \"/products\", \"f1_title\": \"⚡ 2-Min Sizing\", \"f2_title\": \"🎨 Custom Inspo\", \"f3_title\": \"📦 Haute Box\", \"btn1_text\": \"Order Bespoke Nails on WhatsApp\", \"btn2_text\": \"Explore Ready-to-Wear Catalog\"}','2026-09-09 10:43:07','2026-10-21 12:46:14'),(15,'contact','header','{\"badge\": \"Get in Touch\", \"subtitle\": \"Our Parisian studio specialists are ready to assist with custom nail sizing, bespoke press-on designs, and express order dispatch.\", \"title_prefix\": \"The\", \"title_suffix\": \"Lounge\", \"title_highlight\": \"Concierge\"}','2026-09-11 10:44:55','2026-09-11 10:47:28'),(16,'contact','cards','{\"email\": \"concierge@recoltenails.com\", \"address\": \"12 Rue de la Paix, 75001 Paris, France. By appointment only.\", \"hours_tz\": \"Paris Time\", \"hours_sat\": \"10:00 AM – 6:00 PM\", \"hours_sun\": \"12:00 PM – 5:00 PM\", \"email_desc\": \"For wholesale inquiries, press collaborations, and custom bridal suites.\", \"email_title\": \"Email Atelier\", \"hours_title\": \"Concierge Hours\", \"address_title\": \"Paris Atelier\", \"hours_mon_fri\": \"9:00 AM – 8:00 PM\", \"whatsapp_desc\": \"Chat directly with our studio artists for instant sizing help and real-time guidance.\", \"whatsapp_title\": \"WhatsApp Concierge\", \"whatsapp_btn_text\": \"Open Direct WhatsApp\", \"hours_response_badge\": \"WhatsApp response typically under 2 minutes\"}','2026-09-11 10:47:10','2026-09-11 10:47:28'),(17,'contact','topics_widget','{\"badge\": \"Direct Specialist Connection\", \"topics\": [{\"id\": \"sizing\", \"msg\": \"Hello Recolte Nails, I need assistance with nail sizing.\", \"label\": \"Sizing & Curve Fit\"}, {\"id\": \"custom\", \"msg\": \"Hello Recolte Nails, I would like to discuss a custom nail design.\", \"label\": \"Custom Press-On Art\"}, {\"id\": \"care\", \"msg\": \"Hello Recolte Nails, I have a query regarding nail care and top coats.\", \"label\": \"Nail Care & Top Coats\"}, {\"id\": \"shades\", \"msg\": \"Hello Recolte Nails, I would like shade recommendations from your catalog.\", \"label\": \"Gel Polish & Colors\"}, {\"id\": \"order\", \"msg\": \"Hello Recolte Nails, I have an inquiry regarding my order status.\", \"label\": \"Order & Delivery\"}, {\"id\": \"wholesale\", \"msg\": \"Hello Recolte Nails, I am interested in wholesale / salon orders.\", \"label\": \"Wholesale & Salon B2B\"}], \"btn_text\": \"Start WhatsApp Conversation\", \"subtitle\": \"Select the topic that best fits your needs, and our studio artists will prepare customized answers before your WhatsApp chat opens.\", \"badge1_text\": \"Direct Artists\", \"badge2_text\": \"< 2-Min Reply\", \"badge3_text\": \"Zero Waiting\", \"title_prefix\": \"Choose Your\", \"title_highlight\": \"Inquiry Topic\"}','2026-09-11 10:47:10','2026-10-18 08:00:09'),(18,'catalog','hero','{\"badge\": \"HAUTE NAIL COUTURE & CARE ARCHIVES\", \"description\": \"Artisanal salon-quality press-on nails, salon-grade Japanese gel polishes, magnetic cat-eye glazes, and 24K gold cuticle elixirs designed for zero natural nail damage.\", \"title_prefix\": \"The Atelier\", \"title_highlight\": \"Catalog\"}','2026-09-11 11:05:11','2026-09-11 11:05:11');
