INSERT INTO `products` VALUES (20,'recolte-10-shades-cat-eye-gel-polish-kit-e-series','Recolte 10 Shades Cat Eye Gel Polish Kit (E-Series)','10-shade magnetic glass cat eye gel collection with multi-dimensional depth',NULL,12,'Cat Eye Gels',NULL,NULL,4.90,162,1,1,30,'/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_2_.jpg','[\"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_2_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_bottle_2_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_1_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_3_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_Video.mp4\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_4_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_5_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_6_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_7_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_8_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_9_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_10_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_11_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_12_.jpg\", \"/uploads/products/catalog/CATEYES_E_SERIES_10_SHADES_KIT_10colors_cat_eye_13_.jpg\"]','The E-Series provides 10 ethereal, luminous shades featuring sheer crystalline glass bases paired with ultra-reflective magnetic shimmer. Creates an oceanic depth that shifts dynamically under movement and changing light angles.','[\"Ultra-Fine Rare-Earth Magnetic Particles\", \"Fluid Velvet Movement\", \"Smooth 60s LED Cure\", \"Non-Yellowing Formula\"]','Pure Crystalline Resin, Magnetic Iron Oxides, High-Purity Photoinitiator Blend','1. Apply base coat or black base for maximum contrast and cure. 2. Brush on E-Series Cat Eye. 3. Manipulate magnetic shimmer with styling wand. 4. Cure 60 seconds.','[{\"hex\": \"#E8EFF5\", \"name\": \"#001 Clear Glass Glaze\"}, {\"hex\": \"#989445\", \"name\": \"#002 Golden Olive Cat Eye\"}, {\"hex\": \"#886E4B\", \"name\": \"#003 Smoky Bronze Cat Eye\"}, {\"hex\": \"#3D6B7D\", \"name\": \"#004 Ocean Deep Teal Cat Eye\"}, {\"hex\": \"#C33D7B\", \"name\": \"#005 Fuchsia Berry Cat Eye\"}, {\"hex\": \"#686C6A\", \"name\": \"#006 Titanium Charcoal Cat Eye\"}, {\"hex\": \"#1FA3B2\", \"name\": \"#007 Aqua Cyan Cat Eye\"}, {\"hex\": \"#C27A38\", \"name\": \"#008 Amber Copper Cat Eye\"}, {\"hex\": \"#B62C47\", \"name\": \"#009 Ruby Crimson Cat Eye\"}, {\"hex\": \"#8F5877\", \"name\": \"#010 Amethyst Mauve Cat Eye\"}]','[\"Complete 10-Shade Set (15ml each)\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(19,'recolte-24-shades-cat-eye-gel-polish-kit-a-series','Recolte 24 Shades Cat Eye Gel Polish Kit (A-Series)','24-shade magnetic velvet cat eye gel polish collection with deep galaxy refraction',NULL,12,'Cat Eye Gels',NULL,NULL,4.90,155,1,1,29,'/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_4_.jpg','[\"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_4_.jpg\", \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye.mp4\", \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_5_.jpg\", \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_6_.jpg\", \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_Recolte-24_Cat_Eye_7_.jpg\", \"/uploads/products/catalog/CATEYES_A_SERIES_24_SHADES_KIT_bottle_2_.jpg\"]','The A-Series collection encompasses 24 bewitching magnetic jewel tones saturated with rare-earth magnetic micro-prisms. Using the included dual-ended stylus magnet, create velvet glow lines, cosmic halos, and cat-eye light bars in seconds.','[\"24 Vibrant Magnetic Shimmers\", \"Dual-Action Magnet Compatible\", \"Velvet & Cat Eye Line Transitions\", \"4-Week Chip-Free Gloss\"]','Japanese Acrylate Gel, Micronized Rare-Earth Magnetic Particles, Cosmetic Mica, UV Blockers','1. Apply base coat and cure. 2. Apply 1 coat of Recolte Cat Eye gel. 3. Hover magnet 2mm over the wet gel for 5-10 seconds to create desired pattern. 4. Immediately cure 60s. 5. Seal with Top Coat.','[{\"hex\": \"#184D3B\", \"name\": \"Cosmic Emerald\"}, {\"hex\": \"#D48C9A\", \"name\": \"Rose Quartz Velvet\"}, {\"hex\": \"#6C4675\", \"name\": \"Amethyst Gaze\"}, {\"hex\": \"#C5A880\", \"name\": \"Solar Gold\"}]','[\"Full 24-Piece Atelier Kit (15ml each)\", \"Individual 15ml Bottle\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(18,'recolte-3d-sculpture-carving-gel','Recolte 3D Carving Gel','Non-sticky moldable 3D carving gel for sculpted florals, lace & relief nail art',NULL,11,'Carving Gel',NULL,NULL,4.90,148,1,1,28,'/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_1_.jpg','[\"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_1_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_2_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_3_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_1_.mp4\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_4_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_5_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_6_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_7_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_8_.jpg\", \"/uploads/products/catalog/CARVING_GEL_3D_Carving_Gel_9_.jpg\"]','Recolte 3D Carving Gel provides a sculptable clay-like texture that can be rolled, pressed, and shaped with silicone tools or fingers without sticking. Allows unlimited working time to craft ornate floral petals, lace textures, and modern 3D emboss designs.','[\"Kneadable Non-Sticky Texture\", \"Holds Intricate 3D Details Without Slumping\", \"Zero Tack After Curing\", \"Unlimited Work Time Before UV Cure\"]','Solid Sculpting Oligomers, Silica Micro-Spheres, Fine Cosmetic Pigments','1. Take a small bead with a spatula or silicone tool. 2. Roll into desired shape and press onto cured gel manicure. 3. Sculpt petals or relief patterns. 4. Cure for 60 seconds.','[{\"hex\": \"#FFFFFF\", \"name\": \"01\"}, {\"hex\": \"#FFFFFF\", \"name\": \"02\"}, {\"hex\": \"#FFFFFF\", \"name\": \"03\"}, {\"hex\": \"#FFFFFF\", \"name\": \"04\"}, {\"hex\": \"#FFFFFF\", \"name\": \"05\"}, {\"hex\": \"#FFFFFF\", \"name\": \"06\"}]','[\"5gm\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(17,'recolte-sculpting-master-builder-gel','Recolte Sculpting Master Builder Gel','High-viscosity professional builder gel for long extensions, forms & tip overlays',NULL,7,'Builder Gel',NULL,NULL,4.95,141,1,1,27,'/uploads/products/catalog/BUILDER_GEL_builder_gel_1_.png','[\"/uploads/products/catalog/BUILDER_GEL_builder_gel_1_.png\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_3_.png\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_1_.mp4\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_2_.png\", \"/uploads/products/catalog/BUILDER_GEL_artboard_1.jpg\", \"/uploads/products/catalog/BUILDER_GEL_video_showcase.mp4\", \"/uploads/products/catalog/BUILDER_GEL_artboard_2.jpg\", \"/uploads/products/catalog/BUILDER_GEL_artboard_3.jpg\", \"/uploads/products/catalog/BUILDER_GEL_artboard_4.jpg\", \"/uploads/products/catalog/BUILDER_GEL_artboard_5.jpg\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_2_.jpg\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_5_.jpg\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_6_.png\", \"/uploads/products/catalog/BUILDER_GEL_builder_gel_7_.png\"]','Formulated for salon master nail technicians, Recolte Master Builder Gel features exceptional architectural viscosity that holds its shape without running into lateral sidewalls. Yields glass-clear transparency and extreme impact resistance.','[\"Extra High Viscosity\", \"Does Not Run into Cuticles\", \"Rock-Solid Strength & Flexibility\", \"Crystal Clear Clarity\"]','High-Density Urethane Dimethacrylate, Non-Yellowing Optical Clarifiers, Photo-Curing Resins','1. Prep natural nails and apply primer & base coat. 2. Position nail form or tip. 3. Sculpt apex and length with a gel brush. 4. Cure 60-90s under UV/LED. 5. Wipe dispersion layer, file to shape, and seal.','[{\"hex\": \"#F4C7CB\", \"name\": \"01\"}, {\"hex\": \"#F4C7CB\", \"name\": \"02\"}, {\"hex\": \"#F4C7CB\", \"name\": \"03\"}, {\"hex\": \"#F4C7CB\", \"name\": \"04\"}, {\"hex\": \"#F4C7CB\", \"name\": \"05\"}, {\"hex\": \"#F4C7CB\", \"name\": \"06\"}, {\"hex\": \"#F4C7CB\", \"name\": \"07\"}, {\"hex\": \"#F4C7CB\", \"name\": \"08\"}, {\"hex\": \"#F4C7CB\", \"name\": \"09\"}, {\"hex\": \"#F4C7CB\", \"name\": \"10\"}, {\"hex\": \"#F4C7CB\", \"name\": \"11\"}, {\"hex\": \"#F4C7CB\", \"name\": \"12\"}, {\"hex\": \"#F4C7CB\", \"name\": \"13\"}]','[\"15ml\", \"30ml\", \"50ml\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(16,'recolte-fast-spread-blooming-gel','Recolte Fast-Spread Blooming Gel','Instant blooming gel for artistic marble, watercolor bloom & blossom effects',NULL,10,'Blooming Gel',NULL,NULL,4.90,134,1,1,26,'/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_1_.jpg','[\"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_1_.jpg\", \"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_2_.jpg\", \"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_.mp4\", \"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_3_.jpg\", \"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_4_.jpg\", \"/uploads/products/catalog/BLOOMING_GEL_Blooming_gel_fast_5_.jpg\"]','Unlock effortless Parisian nail artistry with Recolte Fast-Spread Blooming Gel. Applied wet over cured color, it gently diffuses drops of gel polish into fluid watercolor petals, organic marble veins, and smoke clouds before curing.','[\"Creates Instant Marble & Rose Effects\", \"Controlled Fluid Diffusion\", \"Compatible with All Gel Polish Colors\", \"No Special Brushes Required\"]','Low Surface-Tension Acrylic Monomers, Optical Diffusion Fluid, UV Curatives','1. Apply background color and cure. 2. Apply a thin, uncured layer of Blooming Gel. 3. Dot or line your desired gel polish into the wet surface and watch it bloom into shape. 4. Cure 60s once desired bloom is achieved, then seal with Top Coat.','[{\"hex\": \"#FFFFFF\", \"name\": \"Clear Bloom Base\"}]','[\"15ml Studio Bottle\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(15,'recolte-biab-liquid-builder-gel','Recolte BIAB Liquid Builder Gel','Self-leveling liquid builder in a bottle for natural nail overlays & apex strength',NULL,9,'BIAB',NULL,NULL,4.95,127,1,1,25,'/uploads/products/catalog/BIAB_Liquid_Builder_Gel_6_.jpg','[\"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_6_.jpg\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_2_.jpg\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_1_.mp4\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_5_.jpg\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_4_.jpg\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_1_.jpg\", \"/uploads/products/catalog/BIAB_Liquid_Builder_Gel_3_.jpg\"]','Recolte BIAB (Builder in a Bottle) offers the ideal balance of brush-on convenience and structural sculpting strength. Its self-leveling formula fills natural ridges, reinforces delicate nails, and allows effortless apex architecture without heat spikes.','[\"Effortless Brush-On Application\", \"Auto Self-Leveling Formula\", \"Builds Natural Apex & Structure\", \"Zero Heat Spike Technology\"]','Japanese Oligomer Resin, Micro-Fiber Reinforcing Matrix, Optical Stabilizers','1. Apply Recolte Base Coat and cure 60s. 2. Apply a thin slip layer of BIAB, then place a bead near the cuticle and gently guide it towards the free edge to build the apex. 3. Flash cure 10s, then full cure 60s.','[{\"hex\": \"#E8B4B8\", \"name\": \"01\"}, {\"hex\": \"#E8B4B8\", \"name\": \"02\"}, {\"hex\": \"#E8B4B8\", \"name\": \"03\"}, {\"hex\": \"#E8B4B8\", \"name\": \"04\"}, {\"hex\": \"#E8B4B8\", \"name\": \"05\"}, {\"hex\": \"#E8B4B8\", \"name\": \"06\"}, {\"hex\": \"#E8B4B8\", \"name\": \"07\"}, {\"hex\": \"#E8B4B8\", \"name\": \"08\"}, {\"hex\": \"#E8B4B8\", \"name\": \"09\"}]','[\"15ml Brush-On Bottle\", \"50ml Studio Jar\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(21,'recolte-208-colors-master-salon-gel-polish-suite','Recolte 208 Colors Master Salon Gel Polish','Complete salon master suite of 208 luxury shades with comprehensive color book & display charts','NEW!',3,'Gel Polishes',0.00,NULL,4.90,169,1,1,0,'/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors.jpg','[\"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Original_Video.mp4\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_4_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors.mp4\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_5_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_Recolte-208_colors_6_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_book_with_bottle_1_.png\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_book_with_bottle_2_.png\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_chart_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_chart_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_chart_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_color_chart_4_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_effect_picture_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_effect_picture_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_effect_picture_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_effect_picture_4_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_208_colors_set_effect_picture_5_.jpg\", \"http://localhost:8000/uploads/products/shade_1792608590_0_image3.jpg\"]','The magnum opus of Recolte Nails Paris. 208 opulent shades spanning runway nudes, sultry bordeaux, energetic neons, sophisticated pastels, and timeless crèmes. Comes complete with a hardcover collector swatch book and studio color charts.','[]','100% Japanese Resin Base, Cosmetic Grade Optical Pigments, Non-Yellowing Stabilizers','1. Prep natural nail and apply base coat; cure 60s. 2. Apply 1-2 thin coats of color; cure 60s per coat. 3. Seal with Recolte Top Coat; cure 60s.','[]','[\"15ml\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(43,'recolte-32-shades-salon-gel-polish-kit','Recolte 32 Shades Salon Gel Polish Kit','32 curated salon capsule shades with high-pigment density and luxury display swatch board',NULL,3,'Gel Polishes',NULL,NULL,4.92,145,1,1,36,'/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_2_.jpg','[\"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_Recolte-32_colors.mp4\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_4_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_5_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_6_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_7_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_8_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_9_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_10_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_11_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_12_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_13_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_14_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_15_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_32_SHADES_KIT_32-colors-set_16_.jpg\"]','The Recolte 32 Shades Kit is an expertly curated capsule collection created for boutique salons and mobile nail artists. Featuring 32 versatile, high-demand hues from velvety nude foundations to bold statement tones, each formula delivers flawless one-stroke opacity, zero shrinkage, and lasting salon radiance. Includes 32 color bottles (8ml each) and a professional counter display swatch board.','[\"32 Hand-Curated Capsule Color Palette\", \"Includes Counter Swatch Display Board\", \"One-Coat Maximum Opacity & Self-Leveling\", \"Zero Shrinkage & 4-Week High-Gloss Wear\", \"Deluxe Royal Navy & Gold Gift Box Presentation\"]','100% Japanese Resin Base, Cosmetic Grade Optical Pigments, Non-Yellowing UV Stabilizers','1. Prep natural nail with Recolte Primer & Base Coat; cure 60s. 2. Apply 1-2 thin coats of your selected 32 Kit color; cure 60s per coat. 3. Seal with Recolte Top Coat; cure 60s.','[]','[\"8ml\"]','2026-10-22 03:41:37','2026-10-22 03:41:37'),(22,'recolte-150-shades-classic-gel-polish-luxury-collection','Recolte 150 Shades Classic Gel Polish Luxury Collection','150-color prestige salon collection curated for bridal, fashion & editorial nail design',NULL,3,'Gel Polishes',NULL,NULL,4.90,176,0,1,32,'/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors.jpg','[\"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors.mp4\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_4_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_5_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_150-colors-set_6_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors_1_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors_2_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors_3_.jpg\", \"/uploads/products/catalog/GEL_POLISHES_150_SHADES_KIT_Recolte-150_colors_4_.jpg\"]','Curated by Parisian colorists, the 150-Shade Collection offers a comprehensive palette tailored for luxury salons and discerning artists. Smooth buttery application ensures streak-free coverage in a single stroke.','[\"150 Trend-Forward Shades\", \"Precision Curved Ergonomic Brush\", \"High Gloss Mirror Reflection\", \"Low-Odor Eco Formula\"]','Ethical Acrylate Oligomer, Pure Organic Colorants, Low-Odor Photoinitiators','1. Apply base coat and cure 60s. 2. Apply 2 thin coats of gel polish, curing each for 60s. 3. Finish with high-gloss top coat.','[]','[\"8ml\", \"15ml\"]','2026-09-26 13:16:40','2026-10-21 14:55:56'),(44,'recolte-professional-air-brush-gun','Recolte Professional Air Brush Gun','Rechargeable cordless micro-mist airbrush system for seamless ombre, aura blush & nail art',NULL,27,'Air Brush',NULL,NULL,4.96,112,1,1,50,'/uploads/products/catalog/AIR_BRUSH_recolte_air_brush_1_.jpg','[\"/uploads/products/catalog/AIR_BRUSH_recolte_air_brush_1_.jpg\", \"/uploads/products/catalog/AIR_BRUSH_recolte_air_brush_2_.jpg\", \"/uploads/products/catalog/AIR_BRUSH_recolte_air_brush_3_.jpg\"]','The Recolte Professional Air Brush Gun is an ultra-fine cordless airbrushing system designed specifically for precision nail artistry and salon beauty treatments. Featuring a high-pressure micro-compressor with smooth dual-action airflow control, it delivers an ultra-fine atomized mist for seamless baby-boomer gradients, aura blush nails, and intricate stencil designs. Equipped with a high-capacity rechargeable battery, interchangeable fluid cups, and professional cleaning brushes.','[\"Cordless & Portable Handheld Design\", \"Ultra-Fine 0.3mm Nano Mist Atomization\", \"Effortless Gradient & Aura Blush Nail Art\", \"Dual-Action Trigger for Precision Control\", \"Includes 3 Fluid Cups & Studio Cleaning Needles\", \"USB-C Fast Charging Long-Life Battery\"]','Precision 0.3mm Atomization Nozzle, Aircraft-Grade Aluminum Alloy Body, High-Torque Micro Diaphragm Compressor, USB-C Fast-Charging Lithium Battery (800mAh), Modular Stainless & High-Clear Fluid Cups','1. Connect the airbrush gun firmly onto the rechargeable compressor base. 2. Dilute your chosen Recolte gel or airbrush ink with Recolte Mixing Gel or alcohol to a milk-like consistency. 3. Add drops to the fluid cup. 4. Press the power button and pull back the trigger to control mist flow from 2-5cm distance. 5. Clean nozzle immediately after use with included cleaning needles and solvent.','[{\"hex\": \"#D4AF37\", \"name\": \"Champagne Gold\"}, {\"hex\": \"#1A1A1A\", \"name\": \"Obsidian Black\"}, {\"hex\": \"#E0A899\", \"name\": \"Rose Pink\"}]','[\"Complete Professional Atelier Kit\"]','2026-10-22 03:41:37','2026-10-22 03:41:37'),(23,'recolte-96-shades-signature-gel-polish-set','Recolte 96 Shades Signature Gel Polish Luxurious Salon Kit','96 runway-inspired signature shades engineered for salon artists and bespoke manicures',NULL,3,'